d->id }}"><input type="hidden" name="quantity" value="1"><input type="hidden" name="action" value="add"><button class="add" aria-label="Add {{ $food->name }} to cart">Order now</button></form>@else<span class="muted">Unavailable</span>@endif</div></div></article>@endforeach</div><p id="empty-search" hidden>No dishes match your search.</p>@if($foods->isEmpty())<div class="empty"><h3>Our menu is being prepared.</h3><p>Please check back soon.</p></div>@endif</section>
