@section('scripts')<script>let category='all';const search=document.querySelector('#search');function filter(){let count=0;document.querySelectorAll('.dish').forEach(card=>{card.hidden=!((category==='all'||card.dataset.category===category)&&card.dataset.search.includes(search.value.toLowerCase().trim()));if(!card.hidden)count++});document.querySelector('#empty-search').hidden=count!==0;}search.addEventListener('input',filter);document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false')});filter()}));</script>@endsection